// pattern: Functional Core
//
//! THROWAWAY diagnostic — delete after use. Discriminates the two MM-473 sub-hypotheses
//! by walking a real exported repo CAR:
//!   (1) prefix over-scan  — `entries_prefixed` yields a key outside the requested prefix
//!   (2) keyed-descent bug — every yielded key carries the prefix, but `get_raw` returns None
//! Set CAR_PROBE_PATH to an exported repo CAR; the test no-ops when unset.

use atrium_repo::blockstore::CarStore;
use atrium_repo::repo::Repository;
use atrium_repo::Cid;
use futures::StreamExt;
use ipld_core::ipld::Ipld;
use std::collections::BTreeMap;
use std::io::Cursor;

const TARGETS: &[&str] = &[
    "community.lexicon.calendar.rsvp",
    "coop.hypha.spores.social.takenFlower",
    "dev.cocore.compute.termsAcceptance",
    "dev.cocore.compute.paymentAuthorization",
];

#[tokio::test]
async fn car_probe() {
    let Ok(path) = std::env::var("CAR_PROBE_PATH") else {
        println!("CAR_PROBE_PATH unset — skipping");
        return;
    };
    let bytes = std::fs::read(&path).expect("read CAR");
    let mut store = CarStore::open(Cursor::new(bytes.as_slice()))
        .await
        .expect("open CAR");
    let root: Cid = store.roots().next().expect("one root");
    let mut repo = Repository::open(&mut store, root).await.expect("open repo");

    // ── 1. Full unprefixed MST walk: ground truth for per-collection counts ──
    let mut all: Vec<String> = Vec::new();
    {
        let mut tree = repo.tree();
        let mut s = Box::pin(tree.entries());
        while let Some(r) = s.next().await {
            let (k, _cid) = r.expect("walk entry");
            all.push(k);
        }
    }
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for k in &all {
        *counts.entry(k.split('/').next().unwrap_or("")).or_insert(0) += 1;
    }
    println!("\n=== full MST walk: {} entries total ===", all.len());
    for t in TARGETS {
        println!("  {t}: {} entries", counts.get(*t).copied().unwrap_or(0));
    }

    // Sorted collection list, so we can name the neighbour a scan would leak into.
    let colls: Vec<&str> = counts.keys().copied().collect();

    // ── 2. Prefixed walk per failing collection ──
    for t in TARGETS {
        let prefix = format!("{t}/");
        let mut yielded: Vec<String> = Vec::new();
        {
            let mut tree = repo.tree();
            let mut s = Box::pin(tree.entries_prefixed(&prefix));
            while let Some(r) = s.next().await {
                let (k, _cid) = r.expect("walk prefixed entry");
                yielded.push(k);
            }
        }

        let next_coll = colls
            .iter()
            .position(|c| c == t)
            .and_then(|i| colls.get(i + 1))
            .copied()
            .unwrap_or("<none>");

        println!("\n=== {t} ===");
        println!("  full-walk entries : {}", counts.get(*t).copied().unwrap_or(0));
        println!("  entries_prefixed  : {}", yielded.len());
        println!("  next collection   : {next_coll}");

        let foreign: Vec<&String> = yielded.iter().filter(|k| !k.starts_with(&prefix)).collect();
        if foreign.is_empty() {
            println!("  VERDICT: no foreign keys -> hypothesis (1) over-scan REFUTED here");
        } else {
            println!("  VERDICT: OVER-SCAN — {} key(s) outside the prefix:", foreign.len());
            for f in &foreign {
                println!("    {f:?}");
            }
        }

        // ── 3. get_raw on each yielded key, verbatim (no strip/re-concat) ──
        for k in &yielded {
            match repo.get_raw(k).await {
                Ok(Some(_)) => {}
                Ok(None) => println!("  get_raw -> None for verbatim key {k:?}"),
                Err(e) => println!("  get_raw -> Err for verbatim key {k:?}: {e}"),
            }
        }

        // ── 4. Reproduce the production path exactly (strip + re-concat) ──
        for k in &yielded {
            let rkey = k.strip_prefix(&prefix).unwrap_or(k).to_string();
            let full_key = format!("{prefix}{rkey}");
            if full_key != *k {
                println!("  KEY MANGLED: yielded {k:?} -> reconstructed {full_key:?}");
            }
            let v: Result<Option<Ipld>, _> = repo.get_raw(&full_key).await;
            if matches!(v, Ok(None)) {
                println!("  production path NotFound at reconstructed key {full_key:?}");
            }
        }
    }
    println!();
}

